import { heartbeatSchema } from "./schema.js";
import { formatIsoDate, prettyJson } from "./utils.js";

function actionSecret(name) {
  return "${{ secrets." + name + " }}";
}

function actionInput(name) {
  return "${{ github.event.inputs." + name + " }}";
}

export function createRootReadme(config) {
  return `# ${config.projectName}

This package was generated by Project Heartbeat.

## Included repositories

- App repo: ${config.repos.app}
- Screenshots repo: ${config.repos.screenshots || "Not configured"}
- Social repo: ${config.repos.social || "Not configured"}

## Install order

1. Copy each top-level repo folder into the matching GitHub repository.
2. Add the required GitHub Actions secrets listed in \`docs/project-heartbeat/README.md\`.
3. Review \`heartbeat.config.json\` in each repo.
4. Run the generated workflows in dry-run mode first.

## Runtime model

- Setup is static and generated locally.
- Scheduled execution happens in GitHub Actions.
- Long-lived secrets belong in repository or organization secrets, not in the frontend app.
`;
}

export function createInstallManifest(config) {
  return prettyJson({
    generatedAt: new Date().toISOString(),
    schemaVersion: config.schemaVersion,
    projectName: config.projectName,
    repos: config.repos,
    enabledFeatures: Object.entries(config.features)
      .filter(([, enabled]) => enabled)
      .map(([feature]) => feature),
    requiredSecrets: config.secrets
  });
}

export function createRepoReadme(config, role) {
  return `# Project Heartbeat for ${role}

This repository receives Project Heartbeat files for the \`${role}\` role.

## Repo mapping

- App repo: ${config.repos.app}
- Screenshots repo: ${config.repos.screenshots || "Not configured"}
- Social repo: ${config.repos.social || "Not configured"}

## Required secrets

- ${config.secrets.githubToken}: GitHub token for issue and project operations
- ${config.secrets.screenshotsRepoToken}: token with write access to the screenshots repo
- ${config.secrets.linkedInClientId}: LinkedIn client ID for semi-manual social flows
- ${config.secrets.linkedInClientSecret}: LinkedIn client secret for semi-manual social flows
- ${config.secrets.linkedInRefreshToken}: LinkedIn refresh token for semi-manual social flows

## Dry-run guidance

- Use the \`workflow_dispatch\` trigger and set \`dry_run\` to \`true\` first.
- Check the workflow summary and artifacts before enabling schedules.
`;
}

export function createTroubleshootingGuide(config) {
  return `# Troubleshooting

## Common setup failures

- Missing ${config.secrets.githubToken}: Daily Issue Agent will fail to create issues.
- Missing ${config.secrets.screenshotsRepoToken}: Screenshot publishing cannot write into ${config.repos.screenshots || "the screenshots repo"}.
- Missing project owner or project number: Daily Issue Agent will skip GitHub Project validation.
- Blank LinkedIn organization URN: Social artifacts will use placeholder copy.

## Diagnostics

- Trigger workflows manually with \`dry_run\` enabled.
- Confirm the repo mapping in \`heartbeat.config.json\`.
- Confirm workflow permissions are enabled at repo or org level.
`;
}

export function createConfigFile(config) {
  return prettyJson(config);
}

export function createSchemaFile() {
  return prettyJson(heartbeatSchema);
}

export function createDependabotFile() {
  return `version: 2
updates:
  - package-ecosystem: "npm"
    directory: "/"
    schedule:
      interval: "weekly"
    open-pull-requests-limit: 5
    labels:
      - "dependencies"
      - "heartbeat"
`;
}

export function createDailyWorkflow(config) {
  return `name: Heartbeat Daily Issue Agent

on:
  schedule:
    - cron: "${config.daily.schedule}"
  workflow_dispatch:
    inputs:
      dry_run:
        description: "Run diagnostics only"
        required: false
        default: "true"

permissions:
  contents: read
  issues: write
  pull-requests: read
  repository-projects: write

jobs:
  heartbeat-daily:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
      - name: Run daily agent
        env:
          GITHUB_TOKEN: ${actionSecret(config.secrets.githubToken)}
          HEARTBEAT_DRY_RUN: ${actionInput("dry_run")}
        run: node .github/scripts/heartbeat-daily.mjs
`;
}

export function createDailyScript() {
  return `import { readFile } from "node:fs/promises";

const token = process.env.GITHUB_TOKEN;
const dryRun = String(process.env.HEARTBEAT_DRY_RUN || "false") === "true";
const repository = process.env.GITHUB_REPOSITORY;

if (!repository) {
  throw new Error("GITHUB_REPOSITORY is required.");
}

const config = JSON.parse(await readFile(new URL("../../heartbeat.config.json", import.meta.url), "utf8"));
const [owner, repo] = repository.split("/");
const today = new Date().toISOString().slice(0, 10);
const title = (config.daily.issueTitleTemplate || "Daily heartbeat: {{date}}").replace("{{date}}", today);

function api(path, init = {}) {
  return fetch("https://api.github.com" + path, {
    ...init,
    headers: {
      Accept: "application/vnd.github+json",
      Authorization: "Bearer " + token,
      "Content-Type": "application/json",
      ...(init.headers || {})
    }
  });
}

async function lookupProjectField() {
  if (!config.github.projectOwner || !config.github.projectNumber) {
    return { status: "skipped", reason: "Project owner or number missing in config." };
  }

  const query = {
    query: "query($login:String!, $number:Int!) { repositoryOwner(login:$login) { __typename ... on Organization { projectV2(number:$number) { title fields(first:50) { nodes { ... on ProjectV2FieldCommon { name dataType } } } } } ... on User { projectV2(number:$number) { title fields(first:50) { nodes { ... on ProjectV2FieldCommon { name dataType } } } } } } }",
    variables: {
      login: config.github.projectOwner,
      number: Number(config.github.projectNumber)
    }
  };

  const response = await api("/graphql", {
    method: "POST",
    body: JSON.stringify(query)
  });

  if (!response.ok) {
    return { status: "failed", reason: "Project lookup failed with " + response.status + "." };
  }

  const payload = await response.json();
  const project = payload?.data?.repositoryOwner?.projectV2;
  if (!project) {
    return { status: "missing", reason: "Project not found." };
  }

  const field = (project.fields.nodes || []).find((node) => node?.name === config.daily.projectFieldName);
  if (!field) {
    return { status: "missing", reason: "Field " + config.daily.projectFieldName + " not found on project " + project.title + "." };
  }

  return { status: "ok", reason: "Validated field " + config.daily.projectFieldName + " on project " + project.title + "." };
}

async function findExistingIssue() {
  const query = new URLSearchParams({
    labels: config.daily.label,
    state: "open",
    per_page: "100"
  });
  const response = await api("/repos/" + owner + "/" + repo + "/issues?" + query.toString());
  if (!response.ok) {
    throw new Error("Issue lookup failed with " + response.status + ".");
  }
  const issues = await response.json();
  return issues.find((issue) => issue.title === title);
}

async function createIssue(projectStatus) {
  const body = [
    "## Heartbeat",
    "",
    "- Date: " + today,
    "- Project field validation: " + projectStatus.status,
    "- Notes: " + projectStatus.reason,
    "",
    "## Checklist",
    "",
    "- Review Dependabot updates",
    "- Check screenshot freshness",
    "- Review social artifacts"
  ].join("\\n");

  const response = await api("/repos/" + owner + "/" + repo + "/issues", {
    method: "POST",
    body: JSON.stringify({
      title,
      body,
      labels: [config.daily.label]
    })
  });

  if (!response.ok) {
    throw new Error("Issue creation failed with " + response.status + ".");
  }

  const issue = await response.json();
  console.log("Created issue #" + issue.number + ": " + issue.html_url);
}

if (!token) {
  throw new Error("GITHUB_TOKEN is required.");
}

const projectStatus = await lookupProjectField();
console.log("Project validation:", projectStatus.status, "-", projectStatus.reason);

if (dryRun) {
  console.log("Dry run enabled. Would create issue titled:", title);
  process.exit(0);
}

const existing = await findExistingIssue();
if (existing) {
  console.log("Issue already exists:", existing.html_url);
  process.exit(0);
}

await createIssue(projectStatus);
`;
}

export function createScreenshotWorkflow(config) {
  return `name: Heartbeat Screenshot Agent

on:
  schedule:
    - cron: "${config.screenshot.schedule}"
  workflow_dispatch:
    inputs:
      dry_run:
        description: "Run diagnostics only"
        required: false
        default: "true"

permissions:
  contents: read

jobs:
  heartbeat-screenshots:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
      - name: Capture screenshots
        run: |
          ${config.screenshot.captureCommand}
      - name: Publish screenshots to screenshots repo
        env:
          GITHUB_TOKEN: ${actionSecret(config.secrets.screenshotsRepoToken)}
          HEARTBEAT_DRY_RUN: ${actionInput("dry_run")}
        run: node .github/scripts/heartbeat-screenshots.mjs
`;
}

export function createScreenshotScript() {
  return `import { readFile, readdir } from "node:fs/promises";
import path from "node:path";

const token = process.env.GITHUB_TOKEN;
const dryRun = String(process.env.HEARTBEAT_DRY_RUN || "false") === "true";
const repository = process.env.GITHUB_REPOSITORY;
const workspace = process.env.GITHUB_WORKSPACE || process.cwd();

if (!repository) {
  throw new Error("GITHUB_REPOSITORY is required.");
}

const config = JSON.parse(await readFile(new URL("../../heartbeat.config.json", import.meta.url), "utf8"));
const [owner, repo] = repository.split("/");
const outputRoot = path.join(workspace, config.screenshot.outputDirectory);
const publishDate = new Date().toISOString().slice(0, 10);

async function api(pathname, init = {}) {
  return fetch("https://api.github.com" + pathname, {
    ...init,
    headers: {
      Accept: "application/vnd.github+json",
      Authorization: "Bearer " + token,
      "Content-Type": "application/json",
      ...(init.headers || {})
    }
  });
}

async function listFiles(dir, base = dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await listFiles(fullPath, base)));
      continue;
    }
    files.push({
      fullPath,
      relativePath: path.relative(base, fullPath)
    });
  }
  return files;
}

async function uploadFile(destinationRepo, branch, file, destinationPath) {
  const content = await readFile(file.fullPath);
  const encodedPath = destinationPath.split("/").map(encodeURIComponent).join("/");
  const response = await api("/repos/" + destinationRepo + "/contents/" + encodedPath, {
    method: "PUT",
    body: JSON.stringify({
      message: "Heartbeat screenshots from " + owner + "/" + repo + " on " + publishDate,
      content: content.toString("base64"),
      branch
    })
  });

  if (!response.ok) {
    throw new Error("Upload failed for " + destinationPath + " with " + response.status + ".");
  }
}

if (!token) {
  throw new Error("GITHUB_TOKEN is required.");
}

const files = await listFiles(outputRoot);
if (files.length === 0) {
  throw new Error("No screenshot files found in " + outputRoot + ".");
}

const destinationRepo = config.repos.screenshots;
const branch = config.screenshot.publishBranch || "main";

console.log("Found", files.length, "screenshot files.");
console.log("Destination repo:", destinationRepo);

if (dryRun) {
  for (const file of files) {
    console.log("Would upload:", file.relativePath);
  }
  process.exit(0);
}

for (const file of files) {
  const destinationPath = ["captures", publishDate, file.relativePath].join("/");
  await uploadFile(destinationRepo, branch, file, destinationPath);
  console.log("Uploaded", destinationPath);
}
`;
}

export function createSocialWorkflow(config) {
  return `name: Heartbeat Social Agent

on:
  workflow_dispatch:
    inputs:
      dry_run:
        description: "Run diagnostics only"
        required: false
        default: "true"

permissions:
  contents: read
  actions: read

jobs:
  heartbeat-social:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20
      - name: Generate social artifacts
        env:
          HEARTBEAT_DRY_RUN: ${actionInput("dry_run")}
          LINKEDIN_CLIENT_ID: ${actionSecret(config.secrets.linkedInClientId)}
          LINKEDIN_CLIENT_SECRET: ${actionSecret(config.secrets.linkedInClientSecret)}
          LINKEDIN_REFRESH_TOKEN: ${actionSecret(config.secrets.linkedInRefreshToken)}
        run: node .github/scripts/heartbeat-social.mjs
      - name: Upload social artifacts
        uses: actions/upload-artifact@v4
        with:
          name: heartbeat-social-artifacts
          path: ${config.social.artifactDirectory}
`;
}

export function createSocialScript() {
  return `import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const dryRun = String(process.env.HEARTBEAT_DRY_RUN || "false") === "true";
const repository = process.env.GITHUB_REPOSITORY;
const workspace = process.env.GITHUB_WORKSPACE || process.cwd();

const config = JSON.parse(await readFile(new URL("../../heartbeat.config.json", import.meta.url), "utf8"));
const outputDir = path.join(workspace, config.social.artifactDirectory);
const today = new Date().toISOString().slice(0, 10);

const artifact = {
  network: "linkedin",
  publishingMode: config.social.publishingMode,
  organizationUrn: config.social.organizationUrn || "urn:li:organization:placeholder",
  sourceRepos: config.repos,
  suggestedText: [
    "Project Heartbeat update for " + today + ".",
    "",
    "Screenshots are available in " + config.repos.screenshots + ".",
    "Maintenance review issue lives in " + config.repos.app + "."
  ].join("\\n"),
  generatedAt: new Date().toISOString()
};

if (dryRun) {
  console.log("Dry run enabled. Would write LinkedIn artifacts into", outputDir);
  console.log(JSON.stringify(artifact, null, 2));
  process.exit(0);
}

await mkdir(outputDir, { recursive: true });
await writeFile(path.join(outputDir, "linkedin-post.json"), JSON.stringify(artifact, null, 2));
await writeFile(
  path.join(outputDir, "linkedin-post.md"),
  [
    "# LinkedIn Post Draft",
    "",
    artifact.suggestedText,
    "",
    "Organization: " + artifact.organizationUrn,
    "Source screenshots repo: " + config.repos.screenshots,
    "Source social repo: " + config.repos.social
  ].join("\\n")
);

console.log("Generated LinkedIn artifacts for", repository);
`;
}

export function createPackageDocsReadme(config) {
  return `# Project Heartbeat Setup

## What this package contains

- Repo-scoped \`heartbeat.config.json\`
- GitHub Actions workflows
- GitHub helper scripts
- Dependabot config
- Troubleshooting and setup notes

## Required GitHub Actions secrets

- \`${config.secrets.githubToken}\`
- \`${config.secrets.screenshotsRepoToken}\`
- \`${config.secrets.linkedInClientId}\`
- \`${config.secrets.linkedInClientSecret}\`
- \`${config.secrets.linkedInRefreshToken}\`

## Setup checklist

1. Copy each repo folder into the matching repository.
2. Add secrets in repository settings.
3. Review workflow cron schedules, capture commands, and branch names.
4. Run each workflow manually with \`dry_run=true\`.
5. Enable scheduled execution after dry-run passes.

## Generated on

${formatIsoDate()}
`;
}
